CREATE OR REPLACE FUNCTION public.food_items_write()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'INSERT' then
    insert into public.vendor_items
      (id, vendor_id, name, description, image_url, price, category, is_available)
    values (
      coalesce(new.id, gen_random_uuid()), new.restaurant_id, new.name,
      new.description, new.image_url, coalesce(new.price, 0), new.category,
      coalesce(new.is_available, true)
    )
    returning id into new.id;
    return new;
  elsif tg_op = 'UPDATE' then
    update public.vendor_items set
      name = new.name, description = new.description, image_url = new.image_url,
      price = new.price, category = new.category, is_available = new.is_available
    where id = old.id;
    return new;
  else
    delete from public.vendor_items where id = old.id;
    return old;
  end if;
end $function$

